function postReqSesion(body: unknown, cookie: string | null): Request {
  return new Request('http://localhost/api/problematicas/parte', {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      ...(cookie ? { cookie } : {}),
    },
    body: JSON.stringify(body),
  })
}

