// Batch E1: el enlace opcional `verificacion: { id, token }` en el body del
// POST enlaza el movimiento recién creado con la verificación de origen
// (infra_verificacion.movimiento_id) y la pasa a 'respondida'/'con_afectacion'.
// Es best-effort: cualquier fallo del enlace NUNCA bloquea el guardado del
// parte.
describe('parte enlaza la verificación de origen (batch E1)', () => {
  async function verificacionPendientePara(cue: string) {
    const episodio = await crearEpisodio({
      periodoId: PERIODO_ENOS_2026_2027_ID,
      nombre: 'Episodio de prueba del parte',
    })
    const creada = await crearVerificacion({
      episodioId: episodio.id,
      cueAnexo: cue,
      solicitadaPorUserId: 'user-director',
    })
    if (!creada.ok) throw new Error(`no se pudo crear la verificación: ${creada.motivo}`)
    return creada
  }

  it('con verificación válida: 201, verificacionVinculada true y la verificación queda respondida/con_afectacion con el movimientoId', async () => {
    const { token, verificacion } = await verificacionPendientePara(CUE_H)

    const res = await POST(
      postReq({
        cue: CUE_H,
        idempotencyKey: crypto.randomUUID(),
        rigeDesde: new Date().toISOString(),
        afectacionesNuevas: [{ motivo: 'Inundación', severidad: 'Alta', secciones: [seccionId(CUE_H, '10')] }],
        verificacion: { id: verificacion.id, token },
      }),
    )
    expect(res.status).toBe(201)
    const body = await res.json()
    expect(body.verificacionVinculada).toBe(true)

    const fila = await obtenerVerificacion(verificacion.id)
    expect(fila?.estado).toBe('respondida')
    expect(fila?.resultado).toBe('con_afectacion')
    expect(fila?.movimientoId).toBe(body.movimientoId)
  })

  it('con token incorrecto: el parte se guarda igual (201), verificacionVinculada false y la verificación sigue pendiente', async () => {
    const { verificacion } = await verificacionPendientePara(CUE_I)

    const res = await POST(
      postReq({
        cue: CUE_I,
        idempotencyKey: crypto.randomUUID(),
        rigeDesde: new Date().toISOString(),
        afectacionesNuevas: [{ motivo: 'Inundación', severidad: 'Alta', secciones: [seccionId(CUE_I, '10')] }],
        verificacion: { id: verificacion.id, token: 'token-incorrecto' },
      }),
    )
    expect(res.status).toBe(201)
    const body = await res.json()
    expect(body.ok).toBe(true)
    expect(body.verificacionVinculada).toBe(false)
    // El motivo del fallo ahora viaja en la respuesta (antes se perdía).
    expect(body.verificacionVinculoMotivo).toBe('credencial_invalida')

    const fila = await obtenerVerificacion(verificacion.id)
    expect(fila?.estado).toBe('pendiente')
    expect(fila?.movimientoId).toBeNull()

    // Y queda exactamente un evento de auditoría para el operador.
    const eventos = await getDb()
      .select()
      .from(infraVerificacionEvento)
      .where(eq(infraVerificacionEvento.verificacionId, verificacion.id))
    const fallidos = eventos.filter((e) => e.tipo === 'vinculo_fallido')
    expect(fallidos).toHaveLength(1)
    expect(fallidos[0]!.motivo).toBe('credencial_invalida')
    expect(fallidos[0]!.actorTipo).toBe('sistema')
  })

  it('respuesta contradictoria: el parte se guarda igual (201) y deja el motivo y el evento de auditoría', async () => {
    const { token, verificacion } = await verificacionPendientePara(CUE_M)
    // El director ya había contestado 'sin_afectacion' por el enlace público;
    // ahora llega un parte con afectación que intenta enlazar la MISMA
    // verificación con 'con_afectacion': contradicción.
    const previa = await responderPorEnlace({
      verificacionId: verificacion.id,
      token,
      resultado: 'sin_afectacion',
    })
    expect(previa.ok).toBe(true)

    const res = await POST(
      postReq({
        cue: CUE_M,
        idempotencyKey: crypto.randomUUID(),
        rigeDesde: new Date().toISOString(),
        afectacionesNuevas: [{ motivo: 'Inundación', severidad: 'Alta', secciones: [seccionId(CUE_M, '10')] }],
        verificacion: { id: verificacion.id, token },
      }),
    )
    expect(res.status).toBe(201)
    const body = await res.json()
    expect(body.ok).toBe(true)
    expect(body.verificacionVinculada).toBe(false)
    expect(body.verificacionVinculoMotivo).toBe('respuesta_contradictoria')

    // La verificación conserva su respuesta original, sin movimiento asociado.
    const fila = await obtenerVerificacion(verificacion.id)
    expect(fila?.estado).toBe('respondida')
    expect(fila?.resultado).toBe('sin_afectacion')
    expect(fila?.movimientoId).toBeNull()

    const eventos = await getDb()
      .select()
      .from(infraVerificacionEvento)
      .where(eq(infraVerificacionEvento.verificacionId, verificacion.id))
    const fallidos = eventos.filter((e) => e.tipo === 'vinculo_fallido')
    expect(fallidos).toHaveLength(1)
    expect(fallidos[0]!.motivo).toBe('respuesta_contradictoria')
  })

  it('sin el campo verificacion: 201, verificacionVinculada false y sin campo de motivo', async () => {
    const res = await POST(
      postReq({
        cue: CUE_J,
        idempotencyKey: crypto.randomUUID(),
        rigeDesde: new Date().toISOString(),
        afectacionesNuevas: [{ motivo: 'Inundación', severidad: 'Alta', secciones: [seccionId(CUE_J, '10')] }],
      }),
    )
    expect(res.status).toBe(201)
    const body = await res.json()
    expect(body.ok).toBe(true)
    expect(body.verificacionVinculada).toBe(false)
    // Cuando no se intentó el vínculo, la clave del motivo ni siquiera existe.
    expect(body.verificacionVinculoMotivo).toBeUndefined()
  })

  it('con verificacion de forma inválida: no rompe, se ignora y el parte se guarda igual', async () => {
    const res = await POST(
      postReq({
        cue: CUE_K,
        idempotencyKey: crypto.randomUUID(),
        rigeDesde: new Date().toISOString(),
        afectacionesNuevas: [{ motivo: 'Inundación', severidad: 'Alta', secciones: [seccionId(CUE_K, '10')] }],
        verificacion: { id: 123 },
      }),
    )
    expect(res.status).toBe(201)
    const body = await res.json()
    expect(body.ok).toBe(true)
    expect(body.verificacionVinculada).toBe(false)
  })

  // Hallazgo de revisión N2: la primera versión del enlace sólo cubría el
  // camino de transacción nueva (201); un retry idéntico (mismo
  // idempotencyKey) entra por el camino de replay idempotente
  // (`movimientoExistente`, 200) y también debe enlazar la verificación —
  // el director puede reintentar por una red inestable sin perder el vínculo.
  it('retry idéntico (mismo idempotencyKey): también enlaza la verificación en el replay (200)', async () => {
    const { token, verificacion } = await verificacionPendientePara(CUE_L)
    const idempotencyKey = crypto.randomUUID()
    const cuerpo = {
      cue: CUE_L,
      idempotencyKey,
      rigeDesde: new Date().toISOString(),
      afectacionesNuevas: [{ motivo: 'Inundación', severidad: 'Alta', secciones: [seccionId(CUE_L, '10')] }],
      verificacion: { id: verificacion.id, token },
    }

    const primera = await POST(postReq(cuerpo))
    expect(primera.status).toBe(201)
    const bodyPrimera = await primera.json()
    expect(bodyPrimera.verificacionVinculada).toBe(true)

    const segunda = await POST(postReq(cuerpo))
    expect(segunda.status).toBe(200)
    const bodySegunda = await segunda.json()
    expect(bodySegunda.verificacionVinculada).toBe(true)
    expect(bodySegunda.movimientoId).toBe(bodyPrimera.movimientoId)

    const fila = await obtenerVerificacion(verificacion.id)
    expect(fila?.estado).toBe('respondida')
    expect(fila?.movimientoId).toBe(bodyPrimera.movimientoId)
  })

  // Tercer camino del enlace: la carrera de idempotencia. Otra request con la
  // misma idempotencyKey gana entre el pre-chequeo y el INSERT, ésta choca
  // contra el índice único y cae en el catch de carrera (route.ts). Ese camino
  // relee el movimiento ganador y también DEBERÍA enlazar la verificación.
  //
  // HALLAZGO de esta revisión adversarial (batch E1): antes NO enlazaba y
  // además respondía 500. El catch de route.ts clasificaba el error con
  // `err.message`, pero drizzle envuelve el error de SQLite: `err.message` es
  // "Failed query: insert ..." y el texto
  // "UNIQUE constraint failed: infra_movimiento.idempotency_key" vive en
  // `err.cause.message`. El regex nunca matcheaba, así que la carrera caía al
  // 500 genérico en vez de re-leer el movimiento ganador y enlazar. Ya
  // corregido: el catch revisa `err.message` y `err.cause.message`, así que
  // este test ahora pasa como `it` normal.
  it('carrera de idempotencia (UNIQUE constraint): el movimiento ganador también enlaza la verificación (200)', async () => {
    const { token, verificacion } = await verificacionPendientePara(CUE_N)
    const idempotencyKey = crypto.randomUUID()

    // Parte preexistente para el CUE: le da un parte_id válido (FK) al
    // movimiento conflictivo y hace que el POST lo trate como actualización.
    const db = getDb()
    const ahora = new Date().toISOString()
    const parteId = crypto.randomUUID()
    await db.insert(infraParte).values({
      id: parteId,
      periodoId: PERIODO_ENOS_2026_2027_ID,
      cueAnexo: CUE_N,
      estadoEstablecimiento: 'habitual',
      estadoEstablecimientoRigeDesde: ahora,
      corteId: 1,
      creadaEn: ahora,
      actualizadaEn: ahora,
    })

    // La inyección ocurre en listarMotivos(), después del pre-chequeo de
    // idempotencia y antes del INSERT de la transacción.
    raceHook.parteId = parteId
    raceHook.idempotencyKey = idempotencyKey

    const res = await POST(
      postReq({
        cue: CUE_N,
        idempotencyKey,
        rigeDesde: ahora,
        afectacionesNuevas: [{ motivo: 'Inundación', severidad: 'Alta', secciones: [seccionId(CUE_N, '10')] }],
        verificacion: { id: verificacion.id, token },
      }),
    )

    expect(res.status).toBe(200)
    const body = await res.json()
    expect(body.verificacionVinculada).toBe(true)

    const fila = await obtenerVerificacion(verificacion.id)
    expect(fila?.estado).toBe('respondida')
    expect(fila?.resultado).toBe('con_afectacion')
    expect(fila?.movimientoId).toBe(body.movimientoId)
  })
})

import { cookies } from 'next/headers'
import { getSessionUser } from '@/lib/session'
import {
  NOMBRE_COOKIE,
  tieneAccesoPublico,
  tieneAccesoPublicoDesdeValorCookie,
} from '@/lib/infraestructura/acceso-publico'
import {
  extraerCookieVerificacionSesion,
  NOMBRE_COOKIE_SESION_VERIFICACION,
  verificacionIdDeSesionValida,
} from '@/lib/infraestructura/verificacion-sesion'
import { verificacionHabilitaSesionEscritura } from '@/lib/infraestructura/verificaciones'

/*
  Guarda del recorrido del parte: contraseña pública O sesión de administrador.

  Por qué existe este módulo y no un cambio dentro de acceso-publico.ts: ese
  archivo se declara la única costura con el mundo público y promete que el día
  que llegue la autenticación por token se reescribe él solo, sin tocar a sus
  llamadores. Meterle la sesión del hub adentro rompería esa promesa —pasaría a
  depender de la base y del rol—, así que la composición vive acá, una capa
  arriba, y él sigue siendo sólo contraseña.

  El rol es 'admin' y no isStaff(): la contraseña se puso porque el contexto del
  parte incluye identidad de alumnos, y ese mismo dato ya tiene una regla de
  acceso escrita en permiso-nominal.ts, donde 'admin' entra sin grant y 'editor'
  queda afuera a propósito. Abrirle la puerta a 'editor' acá contradiría esa
  decisión por la ventana de al lado.

  El orden importa: primero la contraseña, que es una verificación HMAC en
  memoria, y sólo si falla se resuelve la sesión, que consulta la base. Así el
  director —que es quien más entra— nunca paga ese viaje.
*/

async function esAdministrador(): Promise<boolean> {
  const user = await getSessionUser()
  return Boolean(user && !user.banned && user.role === 'admin')
}

/** Para Route Handlers, que reciben la cookie dentro del Request. */
export async function tieneAccesoAlParte(request: Request): Promise<boolean> {
  if (tieneAccesoPublico(request)) return true
  return esAdministrador()
}

/** Para páginas del App Router, que leen la cookie del store de la request. */
export async function tieneAccesoAlParteDesdeCookies(): Promise<boolean> {
  const cookieStore = await cookies()
  if (tieneAccesoPublicoDesdeValorCookie(cookieStore.get(NOMBRE_COOKIE)?.value)) return true
  return esAdministrador()
}

/**
 * Acceso acotado al CUE exacto de una verificación (batch E1): un director
 * que entró por el enlace de "Hay afectación" puede usar el formulario de
 * parte SIN la contraseña compartida, pero SÓLO para ese CUE y sólo mientras
 * la sesión canjeada del token no venció. Nunca amplía a otro CUE ni a rol
 * admin — ver verificacion-sesion.ts para el alcance exacto.
 */
export async function tieneAccesoAlParteParaCue(request: Request, cueAnexo: string): Promise<boolean> {
  if (await tieneAccesoAlParte(request)) return true
  const cookieHeader = request.headers.get('cookie')
  const valor = extraerCookieVerificacionSesion(cookieHeader)
  const verificacionId = verificacionIdDeSesionValida(valor, cueAnexo)
  if (!verificacionId) return false
  return verificacionHabilitaSesionEscritura(verificacionId)
}

/** Para Server Components (app/problematicas/parte/page.tsx). */
export async function tieneAccesoAlParteParaCueDesdeCookies(cueAnexo: string): Promise<boolean> {
  if (await tieneAccesoAlParteDesdeCookies()) return true
  const cookieStore = await cookies()
  const valor = cookieStore.get(NOMBRE_COOKIE_SESION_VERIFICACION)?.value
  const verificacionId = verificacionIdDeSesionValida(valor, cueAnexo)
  if (!verificacionId) return false
  return verificacionHabilitaSesionEscritura(verificacionId)
}

import { createHmac, timingSafeEqual } from 'node:crypto'

// Sesión acotada por CUE, canjeada de la credencial de verificación (batch E1
// del protocolo ENOS). Un director que entra por el enlace de "Hay afectación"
// puede usar el formulario de parte SIN la contraseña compartida, pero SÓLO
// para el CUE exacto de la verificación de la que canjeó, y sólo mientras esta
// sesión no venció.
//
// Por qué una cookie distinta y no reusar la de acceso público: la de acceso
// público prueba "alguien conoce la contraseña compartida" y sirve para todo
// el recorrido; ésta prueba "el servidor emitió esta sesión para ESTE CUE tras
// canjear un token válido". Propósito, payload y cookie distintos. Comparten la
// env var como secreto HMAC porque es un secreto de servidor ya configurado,
// no una credencial de usuario; firmar dos payloads distintos con la misma
// clave no mezcla las sesiones (una firma no es válida para el otro formato).
//
// Alcance: nunca lista ni abre partes de otro CUE, nunca otorga rol admin, ni
// se amplía a ningún otro alcance. La comparación de CUE es parte de la
// validación, no un filtro posterior.

export const NOMBRE_COOKIE_SESION_VERIFICACION = 'verificacion_sesion'
const DURACION_SESION_MS = 1000 * 60 * 30 // 30 minutos

// Duplicada a propósito desde acceso-publico.ts, que la mantiene privada: ese
// archivo se declara la única costura con el mundo público y no exporta sus
// helpers. Importarla acá acoplaría este módulo a su implementación interna;
// mismo criterio que ya usa acceso-parte.ts para no acoplarse.
function obtenerSecreto(): string {
  const secreto = process.env.PROBLEMATICAS_ACCESO_PASSWORD
  if (!secreto) {
    throw new Error('PROBLEMATICAS_ACCESO_PASSWORD no está configurada')
  }
  return secreto
}

function firmar(payload: string, secreto: string): string {
  return createHmac('sha256', secreto).update(payload).digest('base64url')
}

// Comparación en tiempo constante. Nunca uses === contra la firma: filtraría
// por timing dónde difieren.
function iguales(a: string, b: string): boolean {
  const bufA = Buffer.from(a)
  const bufB = Buffer.from(b)
  if (bufA.length !== bufB.length) {
    // Igual comparamos algo del mismo largo que a, para no salir antes y no
    // filtrar por timing que las longitudes no coinciden.
    timingSafeEqual(bufA, bufA)
    return false
  }
  return timingSafeEqual(bufA, bufB)
}

// Token de sesión acotada: "verificacionId|cueAnexo|expiración.firma". Se usa
// `|` como separador porque ni verificacionId (uuid) ni cueAnexo (dígitos) lo
// contienen. La firma prueba que el servidor emitió esta sesión; el CUE dentro
// del payload es lo que acota el acceso.
export function crearSesionVerificacion(
  verificacionId: string,
  cueAnexo: string,
  ahora: Date = new Date(),
): { valorCookie: string; expiraEn: Date } {
  const expiraEn = new Date(ahora.getTime() + DURACION_SESION_MS)
  const payload = `${verificacionId}|${cueAnexo}|${expiraEn.getTime()}`
  const firma = firmar(payload, obtenerSecreto())
  return { valorCookie: `${payload}.${firma}`, expiraEn }
}

type SesionVerificada = { verificacionId: string; cueAnexo: string; expiraEnMs: number }

// Parseo + verificación de firma + expiración de la COOKIE (no de la
// verificación en la base: eso lo re-chequea el llamador contra la fila real,
// ver acceso-parte.ts). Devuelve null ante cualquier fallo de forma, firma o
// vencimiento — nunca lanza.
function verificarSesion(
  valorCookie: string | undefined | null,
  ahora: Date,
): SesionVerificada | null {
  if (!valorCookie) return null
  const separador = valorCookie.indexOf('.')
  if (separador < 0) return null
  const payload = valorCookie.slice(0, separador)
  const firma = valorCookie.slice(separador + 1)
  if (!payload || !firma) return null

  let secreto: string
  try {
    secreto = obtenerSecreto()
  } catch {
    return null
  }
  const firmaEsperada = firmar(payload, secreto)
  if (!iguales(firma, firmaEsperada)) return null

  const [verificacionId, cueAnexoDelToken, expiraEnMsStr] = payload.split('|')
  if (!verificacionId || !cueAnexoDelToken || !expiraEnMsStr) return null

  const expiraEnMs = Number(expiraEnMsStr)
  if (!Number.isFinite(expiraEnMs) || expiraEnMs <= ahora.getTime()) return null

  return { verificacionId, cueAnexo: cueAnexoDelToken, expiraEnMs }
}

export function sesionVerificacionValidaParaCue(
  valorCookie: string | undefined | null,
  cueAnexo: string,
  ahora: Date = new Date(),
): boolean {
  const sesion = verificarSesion(valorCookie, ahora)
  // El CUE pedido tiene que ser el de esta sesión: el acceso nunca se amplía.
  return sesion !== null && sesion.cueAnexo === cueAnexo
}

// Igual que sesionVerificacionValidaParaCue, pero devuelve el verificacionId
// de la sesión en vez de un booleano cuando la cookie es válida PARA ESE CUE
// (firma correcta, CUE coincide, cookie no vencida). Quien llame TODAVÍA debe
// re-chequear la fila de la verificación en la base (estado, revocación,
// vencimiento del token) antes de conceder acceso — esta función sólo prueba
// que la cookie en sí es auténtica y no vencida, no que la verificación siga
// habilitando escritura.
export function verificacionIdDeSesionValida(
  valorCookie: string | undefined | null,
  cueAnexo: string,
  ahora: Date = new Date(),
): string | null {
  const sesion = verificarSesion(valorCookie, ahora)
  if (!sesion || sesion.cueAnexo !== cueAnexo) return null
  return sesion.verificacionId
}

// Opciones para setear la cookie al canjear el token. secure sólo en
// producción para no romper el desarrollo local sobre HTTP.
export function opcionesCookieSesionVerificacion(expiraEn: Date) {
  return {
    httpOnly: true as const,
    sameSite: 'lax' as const,
    secure: process.env.NODE_ENV === 'production',
    expires: expiraEn,
    path: '/',
  }
}

export function extraerCookieVerificacionSesion(
  cookieHeader: string | null | undefined,
): string | undefined {
  if (!cookieHeader) return undefined
  for (const parte of cookieHeader.split(';')) {
    const igual = parte.indexOf('=')
    if (igual < 0) continue
    const clave = parte.slice(0, igual).trim()
    if (clave === NOMBRE_COOKIE_SESION_VERIFICACION) {
      return decodeURIComponent(parte.slice(igual + 1).trim())
    }
  }
  return undefined
}

